    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Each contiguous vertical rail of 5s repeats the adjacent end pattern
    # along the rail's length.
    for c in range(w):
        rail = [r for r in range(h) if g[r][c] == 5]
        if len(rail) < 2:
            continue
        lo, hi = min(rail), max(rail)
        seed_rows = [r for r in range(lo, hi + 1)
                     if any(g[r][x] not in (0, 5) for x in range(c + 1, w))]
        if not seed_rows:
            continue
        seed_rows.sort()
        block = [seed_rows[0]]
        for r in seed_rows[1:]:
            if r == block[-1] + 1:
                block.append(r)
            else:
                block = [r]
        pattern = [[g[r][x] for x in range(c + 1, w)] for r in block]
        for r in range(lo, hi + 1):
            vals = pattern[(r - lo) % len(pattern)]
            for j, value in enumerate(vals, start=c + 1):
                if j < w and value != 5:
                    g[r][j] = value

    # Horizontal rails are contiguous runs; extend the below-rail vertical
    # seed across that run (not across any separate 5-rail elsewhere).
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] != 5:
                c += 1
                continue
            left = c
            while c < w and g[r][c] == 5:
                c += 1
            right = c - 1
            if right - left + 1 < 2:
                continue
            seed_rows = []
            rr = r + 1
            while rr < h and g[rr][left] not in (0, 5):
                seed_rows.append(rr)
                rr += 1
            if not seed_rows:
                continue
            pattern = [g[rr][left] for rr in seed_rows]
            for cc in range(left, right + 1):
                for i, value in enumerate(pattern):
                    rr = r + 1 + i
                    if rr < h and g[rr][cc] != 5:
                        g[rr][cc] = value
    return g
